}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCofferApp: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = CofferApp

    public static func lift(_ handle: UInt64) throws -> CofferApp {
        return CofferApp(unsafeFromHandle: handle)
    }

    public static func lower(_ value: CofferApp) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CofferApp {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: CofferApp, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCofferApp_lift(_ handle: UInt64) throws -> CofferApp {
    return try FfiConverterTypeCofferApp.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCofferApp_lower(_ value: CofferApp) -> UInt64 {
    return FfiConverterTypeCofferApp.lower(value)
}






/**
 * 解锁会话门面（`cf_session::VaultSession` 的 UniFFI Object 包装）。
 */
public protocol VaultSessionProtocol: AnyObject, Sendable {
    
    /**
     * 超时则锁定；返回是否执行了锁定（Swift 定时器驱动）。
     */
    func autoLockIfExpired(nowSecs: Int64)  -> Bool
    
    /**
     * 创建条目，返回新条目 ID（UUIDv7 文本）。
     */
    func createItem(draft: FfiItemDraft) throws  -> String
    
    /**
     * 删除条目：`hard = false` 进回收站，`hard = true` 级联硬删。
     */
    func deleteItem(itemId: String, hard: Bool) throws 
    
    /**
     * 库显示名（锁定时也可见）。
     */
    func displayName()  -> String
    
    /**
     * 生成随机密码（CSPRNG，参数见 [`FfiPasswordGenOptions`]）。
     */
    func generatePassword(opts: FfiPasswordGenOptions) throws  -> String
    
    /**
     * 按需取字段明文值（密码等敏感值，随取随走，docs/07 §4.2）。
     * 条目不存在返回 Err(1011)（ItemNotFound）；条目存在但字段不存在
     * 返回 `None`（QA F-2：文档对齐实现，1011 语义保留）。
     */
    func getFieldValue(itemId: String, fieldId: String) throws  -> String?
    
    /**
     * 读取条目完整详情（Concealed 字段值掩码，docs/07 §4.2）。
     */
    func getItem(itemId: String) throws  -> FfiItemDetails?
    
    /**
     * CSV 导入（单事务 all-or-nothing；锁定态 → 码 1001）。
     */
    func importCsv(path: String) throws  -> FfiCsvImportResult
    
    /**
     * 是否处于解锁态。
     */
    func isUnlocked()  -> Bool
    
    /**
     * 列出条目（updated_at 倒序）；`filter` 传 `None` 为默认全量。
     */
    func listItems(filter: FfiItemFilter?) throws  -> [FfiItemSummary]
    
    /**
     * 锁定：立即清零内存密钥（幂等）。
     */
    func lock() 
    
    /**
     * 解析 otpauth:// URI（仅 SHA-1）；失败 → 码 1012。
     */
    func parseOtpauthUri(uri: String) throws  -> FfiTotpDraft
    
    /**
     * CSV 预检（只读、可反复调用；1Password 9 列，docs/07 §3）。
     */
    func precheckCsv(path: String) throws  -> FfiCsvPrecheckReport
    
    /**
     * 从回收站恢复条目。
     */
    func restoreItem(itemId: String) throws 
    
    /**
     * 标题搜索（多关键词全命中，仅 Active 态；空查询返回空结果）。
     */
    func search(query: String) throws  -> [FfiItemSummary]
    
    /**
     * 设置 / 取消收藏。
     */
    func setFavorite(itemId: String, favorite: Bool) throws 
    
    /**
     * 设置空闲超时秒数（`<= 0` 禁用自动锁定）。
     */
    func setIdleTimeoutSecs(secs: Int64) 
    
    /**
     * 记录最后活动时间（Unix 秒，平台事件驱动喂入）。
     */
    func setLastActivity(unixSecs: Int64) 
    
    /**
     * 密码强度评估（zxcvbn 0–4 + 改进建议）。
     *
     * 与 [`CofferApp::strength_estimate`] 同语义（同一实现委托，见
     * [`strength_estimate_impl`]）；保留于会话对象仅为兼容既有调用方，
     * 无会话场景（建库界面）请走工厂版本。
     */
    func strengthEstimate(candidate: String) throws  -> FfiStrengthEstimate
    
    /**
     * 生成条目当前 TOTP 验证码（共享密钥不出会话层）。
     */
    func totpCode(itemId: String) throws  -> FfiTotpCode
    
    /**
     * 读取条目 TOTP 元数据（**绝不含 secret**，编辑界面展示用）。
     *
     * 返回 algo / digits / period / issuer / account，供编辑界面展示
     * 「已有 TOTP（SHA-1 · 6 位 · 30s）」并默认保留（见
     * [`VaultSession::update_item_with_totp`]）。条目无 TOTP 记录 →
     * `None`。
     */
    func totpConfig(itemId: String) throws  -> FfiTotpMeta?
    
    /**
     * 解锁：NFC 归一化 → Argon2id → DEK 解封 → verifier 校验。
     * 密码错 / 数据篡改统一码 1002（FR-1.4）。
     */
    func unlock(password: String) throws  -> FfiVaultInfo
    
    /**
     * 更新条目（整体替换：fields / urls / tags 删旧插新；TOTP **默认
     * 保留** —— FFI 不下发 secret，编辑无法重提交原密钥，默认删旧会
     * 静默丢失 TOTP）。TOTP 三态显式控制走 [`VaultSession::update_item_with_totp`]。
     */
    func updateItem(itemId: String, draft: FfiItemDraft) throws 
    
    /**
     * 更新条目（TOTP 三态显式版）：`keep` 保留既有加密行 / `replace`
     * 删旧插新 / `remove` 移除。draft 的 `totp` 字段在此路径被忽略。
     */
    func updateItemWithTotp(itemId: String, draft: FfiItemDraft, totp: FfiTotpUpdate) throws 
    
    /**
     * 库工作目录。
     */
    func vaultDir()  -> String
    
    /**
     * 库 UUID（UUIDv7 文本）。
     */
    func vaultUuid()  -> String
    
}
