    typealias SwiftType = FfiDesignation

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiDesignation {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .username
        
        case 2: return .password
        
        case 3: return .totp
        
        case 4: return .notesPlain
        
        case 5: return .email
        
        case 6: return .other(value: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiDesignation, into buf: inout [UInt8]) {
        switch value {
        
        
        case .username:
            writeInt(&buf, Int32(1))
        
        
        case .password:
            writeInt(&buf, Int32(2))
        
        
        case .totp:
            writeInt(&buf, Int32(3))
        
        
        case .notesPlain:
            writeInt(&buf, Int32(4))
        
        
        case .email:
            writeInt(&buf, Int32(5))
        
        
        case let .other(value):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(value, into: &buf)
            
        }
    }
}


