/**
 * FFI 层统一错误（docs/07 §2.3：`code: u16` + `message`）。
 *
 * UniFFI error enum：Swift 侧每个变体对应一个 error case。
 * `Coffer` 承载全部业务错误（按码本地化）；`InternalPanic` 是
 * panic 兜底（docs/07 §5 C-8 / R-2）。
 */
public 
enum FfiError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * 业务错误：`code` 为 docs/03 §12 错误码（1001 锁定 / 1002 解锁失败 /
     * 1003 库不存在 / 1004 库已存在 / 1005 损坏 / 1006 版本过新 / 1007 KDF /
     * 1008 解密 / 1009 存储 / 1010 弱密码 / 1011 条目不存在 / 1012 校验 /
     * 2001 导入格式 / 2002 导入失败 / 2003 导出失败 / 3001 TOTP /
     * 4001–4002 生物识别 / 5001 IO / 5002 参数）。
     */
    case Coffer(
        /**
         * docs/03 §12 稳定错误码
         */code: UInt16, 
        /**
         * 错误摘要（日志用；UI 按 code 本地化，不解析本字段）
         */message: String
    )
    /**
     * Rust panic 兜底（错误码 5999，见模块文档）。
     */
    case InternalPanic(
        /**
         * 脱敏摘要（固定文案 + 载荷类型/字节数指纹，内容永不透传）
         */message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension FfiError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiError: FfiConverterRustBuffer {
    typealias SwiftType = FfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Coffer(
            code: try FfiConverterUInt16.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .InternalPanic(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Coffer(code,message):
            writeInt(&buf, Int32(1))
            FfiConverterUInt16.write(code, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .InternalPanic(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


